// Internal Helpers
// ---------------------------------------------------------------------------

func calc1DArraySize[T any](eleType uint16, arr []T) int {
	eleBytes := 0
	switch eleType {
	case TagBool, TagInt8, TagUint8:
		eleBytes = 1
	case TagInt16, TagUint16:
		eleBytes = 2
	case TagInt32, TagUint32, TagFloat32:
		eleBytes = 4
	case TagInt64, TagUint64, TagFloat64:
		eleBytes = 8
	default:
		eleBytes = 0
	}

	getSizableSize := func(innerArr []T) int {
		size := 0
		for _, item := range innerArr {
			size += ObjectSetUnsetPrefixSize + calcTypeSize(item)
		}
		return size
	}

	switch eleType {
	case TagBool, TagInt8, TagUint8, TagInt16, TagUint16, TagInt32, TagUint32, TagFloat32, TagInt64, TagUint64, TagFloat64:
		return len(arr) * eleBytes
	case TagString, TagBytes:
		size := 0
		for _, item := range arr {
			size += StrOrByteLenPrefixSize + calcTypeSize(item)
		}
		return size

	case TagOnlyScalarTypesMsg:
		return getSizableSize(arr)

	case TagOnlyVariableTypesMsg:
		return getSizableSize(arr)

	case TagAllTypesFieldsMsg:
		return getSizableSize(arr)

	case TagRecursiveNestedMsg:
		return getSizableSize(arr)

	case TagAllTypesOfArraysMsg:
		return getSizableSize(arr)

	default:
		return 0
	}
}

func calcTypeSize(ele any) int {
	switch val := ele.(type) {
	// Primitives
	case bool, int8, uint8:
		return 1
	case int16, uint16:
		return 2
	case int32, uint32, float32:
		return 4
	case int64, uint64, float64:
		return 8

	// Strings & Byte Slices
	case string:
		return len(val)
	case []byte:
		return len(val)

	case Sizable:
		if val != nil {
			return val.Size()
		}
		return 0

	default:
		panic(fmt.Sprintf("calcTypeSize: unsupported type %T", val))
	}
}

func sliceToBytes[T any](eleType uint16, elements any) ([]byte, error) {
	switch arr := elements.(type) {
	case []T:
		overallItemsCount, arrBytes, err := oneDimensionalSliceToBytes(arr)
		if err != nil {
			return nil, fmt.Errorf("failed to serialize 1D slice: %w", err)
		}
		result := make([]byte, (TypeMarkerSize*2)+ArrayCountPrefixSize+len(arrBytes))
		binary.BigEndian.PutUint16(result[0:], TagArray)
		binary.BigEndian.PutUint16(result[2:], eleType)
		binary.BigEndian.PutUint16(result[4:], uint16(overallItemsCount))
		copy(result[6:], arrBytes)
		return result, nil

	case [][]T:
		overallItemsCount, arrBytes, err := twoDimensionalSliceToBytes(arr)
		if err != nil {
			return nil, fmt.Errorf("failed to serialize 2D slice: %w", err)
		}
		result := make([]byte, (TypeMarkerSize*2)+ArrayCountPrefixSize+len(arrBytes))
		binary.BigEndian.PutUint16(result[0:], Tag2DArray)
		binary.BigEndian.PutUint16(result[2:], eleType)
		binary.BigEndian.PutUint16(result[4:], uint16(overallItemsCount))
		copy(result[6:], arrBytes)
		return result, nil

	case [][][]T:
		overallItemsCount, arrBytes, err := threeDimensionalSliceToBytes(arr)
		if err != nil {
			return nil, fmt.Errorf("failed to serialize 3D slice: %w", err)
		}
		result := make([]byte, (TypeMarkerSize*2)+ArrayCountPrefixSize+len(arrBytes))
		binary.BigEndian.PutUint16(result[0:], Tag3DArray)
		binary.BigEndian.PutUint16(result[2:], eleType)
		binary.BigEndian.PutUint16(result[4:], uint16(overallItemsCount))
		copy(result[6:], arrBytes)
		return result, nil

	default:
		return nil, fmt.Errorf("unsupported slice type: %T", arr)
	}
}

func threeDimensionalSliceToBytes[T any](elements [][][]T) (int, []byte, error) {
	count := len(elements)
	if count == 0 {
		return 0, binary.BigEndian.AppendUint16(nil, 0), nil
	}

	if count > int(MaxArrayElements) {
		return 0, nil, fmt.Errorf("array length %d exceeds MaxArrayElements", count)
	}

	itemsCount := 0
	buf := make([]byte, ArrayCountPrefixSize, 512)
	binary.BigEndian.PutUint16(buf[0:], uint16(count))
	for i, v := range elements {
		n, bytes, err := twoDimensionalSliceToBytes(v)
		if err != nil {
			return 0, nil, fmt.Errorf("failed to serialize 2D slice at index %d: %w", i, err)
		}
		buf = append(buf, bytes...)
		itemsCount += n

	}
	return itemsCount, buf, nil
}

func twoDimensionalSliceToBytes[T any](elements [][]T) (int, []byte, error) {
	count := len(elements)
	if count == 0 {
		return 0, binary.BigEndian.AppendUint16(nil, 0), nil
	}

	if count > int(MaxArrayElements) {
		return 0, nil, fmt.Errorf("array length %d exceeds MaxArrayElements", count)
	}

	itemsCount := 0
	buf := make([]byte, ArrayCountPrefixSize, 256)
	binary.BigEndian.PutUint16(buf[0:], uint16(count))
	for i, v := range elements {
		n, bytes, err := oneDimensionalSliceToBytes(v)
		if err != nil {
			return 0, nil, fmt.Errorf("failed to serialize 1D slice at index %d: %w", i, err)
		}
		buf = append(buf, bytes...)
		itemsCount += n
	}
	return itemsCount, buf, nil
}

func oneDimensionalSliceToBytes[T any](elements []T) (int, []byte, error) {
	count := len(elements)
	if count == 0 {
		return 0, binary.BigEndian.AppendUint16(nil, 0), nil
	}

	if count > int(MaxArrayElements) {
		return 0, nil, fmt.Errorf("array length %d exceeds MaxArrayElements", count)
	}

	switch sl := any(elements).(type) {
	// --- 1-Byte Primitives ---
	case []bool:
		buf := make([]byte, ArrayCountPrefixSize+count)
		binary.BigEndian.PutUint16(buf[0:], uint16(count))
		for i, v := range sl {
			if v {
				buf[ArrayCountPrefixSize+i] = 1
			} else {
				buf[ArrayCountPrefixSize+i] = 0
			}
		}
		return count, buf, nil

	case []uint8:
		buf := make([]byte, ArrayCountPrefixSize+count)
		binary.BigEndian.PutUint16(buf[0:], uint16(count))
		copy(buf[ArrayCountPrefixSize:], sl)
		return count, buf, nil

	case []int8:
		buf := make([]byte, ArrayCountPrefixSize+count)
		binary.BigEndian.PutUint16(buf[0:], uint16(count))
		for i, v := range sl {
			buf[ArrayCountPrefixSize+i] = byte(v)
		}
		return count, buf, nil

	// --- 2-Byte Primitives ---
	case []uint16:
		buf := make([]byte, ArrayCountPrefixSize+(count*2))
		binary.BigEndian.PutUint16(buf[0:], uint16(count))
		for i, v := range sl {
			binary.BigEndian.PutUint16(buf[ArrayCountPrefixSize+i*2:], v)
		}
		return count, buf, nil

	case []int16:
		buf := make([]byte, ArrayCountPrefixSize+(count*2))
		binary.BigEndian.PutUint16(buf[0:], uint16(count))
		for i, v := range sl {
			binary.BigEndian.PutUint16(buf[ArrayCountPrefixSize+i*2:], uint16(v))
		}
		return count, buf, nil

	// --- 4-Byte Primitives ---
	case []uint32:
		buf := make([]byte, ArrayCountPrefixSize+(count*4))
		binary.BigEndian.PutUint16(buf[0:], uint16(count))
		for i, v := range sl {
			binary.BigEndian.PutUint32(buf[ArrayCountPrefixSize+i*4:], v)
		}
		return count, buf, nil

	case []int32:
		buf := make([]byte, ArrayCountPrefixSize+(count*4))
		binary.BigEndian.PutUint16(buf[0:], uint16(count))
		for i, v := range sl {
			binary.BigEndian.PutUint32(buf[ArrayCountPrefixSize+i*4:], uint32(v))
		}
		return count, buf, nil

	case []float32:
		buf := make([]byte, ArrayCountPrefixSize+(count*4))
		binary.BigEndian.PutUint16(buf[0:], uint16(count))
		for i, v := range sl {
			binary.BigEndian.PutUint32(buf[ArrayCountPrefixSize+i*4:], math.Float32bits(v))
		}
		return count, buf, nil

	// --- 8-Byte Primitives ---
	case []uint64:
		buf := make([]byte, ArrayCountPrefixSize+(count*8))
		binary.BigEndian.PutUint16(buf[0:], uint16(count))
		for i, v := range sl {
			binary.BigEndian.PutUint64(buf[ArrayCountPrefixSize+i*8:], v)
		}
		return count, buf, nil

	case []int64:
		buf := make([]byte, ArrayCountPrefixSize+(count*8))
		binary.BigEndian.PutUint16(buf[0:], uint16(count))
		for i, v := range sl {
			binary.BigEndian.PutUint64(buf[ArrayCountPrefixSize+i*8:], uint64(v))
		}
		return count, buf, nil

	case []float64:
		buf := make([]byte, ArrayCountPrefixSize+(count*8))
		binary.BigEndian.PutUint16(buf[0:], uint16(count))
		for i, v := range sl {
			binary.BigEndian.PutUint64(buf[ArrayCountPrefixSize+i*8:], math.Float64bits(v))
		}
		return count, buf, nil

	// --- Variable-Length Sequences ---
	case []string:
		totalSize := 0
		for _, v := range sl {
			totalSize += StrOrByteLenPrefixSize + len(v)
		}
		buf := make([]byte, ArrayCountPrefixSize+totalSize)
		binary.BigEndian.PutUint16(buf[0:], uint16(count))
		dynOff := ArrayCountPrefixSize
		for _, v := range sl {
			binary.BigEndian.PutUint32(buf[dynOff:], uint32(len(v)))
			dynOff += StrOrByteLenPrefixSize
			copy(buf[dynOff:], v)
			dynOff += len(v)
		}
		return count, buf, nil

	case [][]byte:
		totalSize := 0
		for _, v := range sl {
			totalSize += StrOrByteLenPrefixSize + len(v)
		}
		buf := make([]byte, ArrayCountPrefixSize+totalSize)
		binary.BigEndian.PutUint16(buf[0:], uint16(count))
		dynOff := ArrayCountPrefixSize
		for _, v := range sl {
			binary.BigEndian.PutUint32(buf[dynOff:], uint32(len(v)))
			dynOff += StrOrByteLenPrefixSize
			copy(buf[dynOff:], v)
			dynOff += len(v)
		}
		return count, buf, nil

	case []*OnlyScalarTypesMsg:
		totalSize := 0
		for _, v := range sl {
			totalSize += ObjectSetUnsetPrefixSize
			if v == nil {
				continue
			}
			totalSize += v.Size()
		}
		buf := make([]byte, ArrayCountPrefixSize+totalSize)
		binary.BigEndian.PutUint16(buf[0:], uint16(count))
		dynOff := ArrayCountPrefixSize
		for _, v := range sl {
			if v == nil {
				buf[dynOff] = 0
				dynOff += ObjectSetUnsetPrefixSize
				continue
			}
			buf[dynOff] = 1
			dynOff += ObjectSetUnsetPrefixSize

			b, err := v.Marshal()
			if err != nil {
				return 0, nil, fmt.Errorf("failed to serialize *OnlyScalarTypesMsg element: %w", err)
			}
			copy(buf[dynOff:], b)
			dynOff += len(b)
		}
		return count, buf, nil

	case []*OnlyVariableTypesMsg:
		totalSize := 0
		for _, v := range sl {
			totalSize += ObjectSetUnsetPrefixSize
			if v == nil {
				continue
			}
			totalSize += v.Size()
		}
		buf := make([]byte, ArrayCountPrefixSize+totalSize)
		binary.BigEndian.PutUint16(buf[0:], uint16(count))
		dynOff := ArrayCountPrefixSize
		for _, v := range sl {
			if v == nil {
				buf[dynOff] = 0
				dynOff += ObjectSetUnsetPrefixSize
				continue
			}
			buf[dynOff] = 1
			dynOff += ObjectSetUnsetPrefixSize

			b, err := v.Marshal()
			if err != nil {
				return 0, nil, fmt.Errorf("failed to serialize *OnlyVariableTypesMsg element: %w", err)
			}
			copy(buf[dynOff:], b)
			dynOff += len(b)
		}
		return count, buf, nil

	case []*AllTypesFieldsMsg:
		totalSize := 0
		for _, v := range sl {
			totalSize += ObjectSetUnsetPrefixSize
			if v == nil {
				continue
			}
			totalSize += v.Size()
		}
		buf := make([]byte, ArrayCountPrefixSize+totalSize)
		binary.BigEndian.PutUint16(buf[0:], uint16(count))
		dynOff := ArrayCountPrefixSize
		for _, v := range sl {
			if v == nil {
				buf[dynOff] = 0
				dynOff += ObjectSetUnsetPrefixSize
				continue
			}
			buf[dynOff] = 1
			dynOff += ObjectSetUnsetPrefixSize

			b, err := v.Marshal()
			if err != nil {
				return 0, nil, fmt.Errorf("failed to serialize *AllTypesFieldsMsg element: %w", err)
			}
			copy(buf[dynOff:], b)
			dynOff += len(b)
		}
		return count, buf, nil

	case []*RecursiveNestedMsg:
		totalSize := 0
		for _, v := range sl {
			totalSize += ObjectSetUnsetPrefixSize
			if v == nil {
				continue
			}
			totalSize += v.Size()
		}
		buf := make([]byte, ArrayCountPrefixSize+totalSize)
		binary.BigEndian.PutUint16(buf[0:], uint16(count))
		dynOff := ArrayCountPrefixSize
		for _, v := range sl {
			if v == nil {
				buf[dynOff] = 0
				dynOff += ObjectSetUnsetPrefixSize
				continue
			}
			buf[dynOff] = 1
			dynOff += ObjectSetUnsetPrefixSize

			b, err := v.Marshal()
			if err != nil {
				return 0, nil, fmt.Errorf("failed to serialize *RecursiveNestedMsg element: %w", err)
			}
			copy(buf[dynOff:], b)
			dynOff += len(b)
		}
		return count, buf, nil

	case []*AllTypesOfArraysMsg:
		totalSize := 0
		for _, v := range sl {
			totalSize += ObjectSetUnsetPrefixSize
			if v == nil {
				continue
			}
			totalSize += v.Size()
		}
		buf := make([]byte, ArrayCountPrefixSize+totalSize)
		binary.BigEndian.PutUint16(buf[0:], uint16(count))
		dynOff := ArrayCountPrefixSize
		for _, v := range sl {
			if v == nil {
				buf[dynOff] = 0
				dynOff += ObjectSetUnsetPrefixSize
				continue
			}
			buf[dynOff] = 1
			dynOff += ObjectSetUnsetPrefixSize

			b, err := v.Marshal()
			if err != nil {
				return 0, nil, fmt.Errorf("failed to serialize *AllTypesOfArraysMsg element: %w", err)
			}
			copy(buf[dynOff:], b)
			dynOff += len(b)
		}
		return count, buf, nil

	default:
		var zero T
		return 0, nil, fmt.Errorf("unsupported primitive type: %T", zero)
	}
}

func validateReaderArrayPrefix[T any](r io.Reader, expectedArrType uint16) error {
	arrType, err := readUint16(r)
	if err != nil {
		return fmt.Errorf("error reading array type marker: %w", err)
	}

	if arrType != expectedArrType {
		return fmt.Errorf("unexpected array type marker: got %d, expected %d", arrType, expectedArrType)
	}

	eleType, err := readUint16(r)
	if err != nil {
		return fmt.Errorf("error reading element type marker: %w", err)
	}

	var zero T
	expectedEleType, err := getElementType(zero)
	if err != nil {
		return fmt.Errorf("error reading element type marker: %w", err)
	}

	if eleType != expectedEleType {
		return fmt.Errorf("unexpected element type marker: got %d, expected %d", eleType, expectedEleType)
	}

	// Skip the overall items count written by sliceToBytes
	_, err = readUint16(r)
	if err != nil {
		return fmt.Errorf("error reading overall items count: %w", err)
	}

	return nil
}

func readThreeDimensionalSlice[T any](r io.Reader) ([][][]T, error) {
	count, err := readUint16(r)
	if err != nil {
		return nil, fmt.Errorf("failed to read 3D array count: %w", err)
	}

	if count > MaxArrayElements {
		return nil, fmt.Errorf("array length %d exceeds MaxArrayElements", count)
	}

	if count == 0 {
		return nil, nil
	}

	// Read the 3D array elements
	slice := make([][][]T, count)
	for i := 0; i < int(count); i++ {
		innerSlice, err := readTwoDimensionalSlice[T](r)
		if err != nil {
			return nil, fmt.Errorf("failed to read 3D array element at index %d: %w", i, err)
		}

		slice[i] = innerSlice
	}
	return slice, nil
}

func readTwoDimensionalSlice[T any](r io.Reader) ([][]T, error) {
	count, err := readUint16(r)
	if err != nil {
		return nil, fmt.Errorf("failed to read 2D array count: %w", err)
	}

	if count > MaxArrayElements {
		return nil, fmt.Errorf("array length %d exceeds MaxArrayElements", count)
	}

	if count == 0 {
		return nil, nil
	}

	// Read the 2D array elements
	slice := make([][]T, count)
	for i := 0; i < int(count); i++ {
		innerSlice, err := readOneDimensionalSlice[T](r)
		if err != nil {
			return nil, fmt.Errorf("failed to read 2D array element at index %d: %w", i, err)
		}

		slice[i] = innerSlice
	}
	return slice, nil
}

func readOneDimensionalSlice[T any](r io.Reader) ([]T, error) {
	count, err := readUint16(r)
	if err != nil {
		return nil, fmt.Errorf("failed to read 1D array count: %w", err)
	}

	if count == 0 {
		return nil, nil
	}

	if count > MaxArrayElements {
		return nil, fmt.Errorf("array length %d exceeds MaxArrayElements", count)
	}

	slice := make([]T, count)

	// Read the 1D array elements
	switch sl := any(slice).(type) {
	// --- 1-Byte Primitives ---
	case []uint8:
		if _, err := io.ReadFull(r, sl); err != nil {
			return nil, fmt.Errorf("failed to read array elements: %w", err)
		}
	case []int8:
		data := make([]byte, count)
		if _, err := io.ReadFull(r, data); err != nil {
			return nil, fmt.Errorf("failed to read array elements: %w", err)
		}
		for i := range sl {
			sl[i] = int8(data[i])
		}
	case []bool:
		data := make([]byte, count)
		if _, err := io.ReadFull(r, data); err != nil {
			return nil, fmt.Errorf("failed to read array elements: %w", err)
		}
		for i := range sl {
			sl[i] = data[i] != 0
		}

	// --- 2-Byte Primitives ---
	case []uint16:
		data := make([]byte, count*2)
		if _, err := io.ReadFull(r, data); err != nil {
			return nil, fmt.Errorf("failed to read array elements: %w", err)
		}
		for i := range sl {
			sl[i] = binary.BigEndian.Uint16(data[i*2:])
		}
	case []int16:
		data := make([]byte, count*2)
		if _, err := io.ReadFull(r, data); err != nil {
			return nil, fmt.Errorf("failed to read array elements: %w", err)
		}
		for i := range sl {
			sl[i] = int16(binary.BigEndian.Uint16(data[i*2:]))
		}

	// --- 4-Byte Primitives ---
	case []uint32:
		data := make([]byte, count*4)
		if _, err := io.ReadFull(r, data); err != nil {
			return nil, fmt.Errorf("failed to read array elements: %w", err)
		}
		for i := range sl {
			sl[i] = binary.BigEndian.Uint32(data[i*4:])
		}
	case []int32:
		data := make([]byte, count*4)
		if _, err := io.ReadFull(r, data); err != nil {
			return nil, fmt.Errorf("failed to read array elements: %w", err)
		}
		for i := range sl {
			sl[i] = int32(binary.BigEndian.Uint32(data[i*4:]))
		}
	case []float32:
		data := make([]byte, count*4)
		if _, err := io.ReadFull(r, data); err != nil {
			return nil, fmt.Errorf("failed to read array elements: %w", err)
		}
		for i := range sl {
			sl[i] = math.Float32frombits(binary.BigEndian.Uint32(data[i*4:]))
		}

	// --- 8-Byte Primitives ---
	case []uint64:
		data := make([]byte, count*8)
		if _, err := io.ReadFull(r, data); err != nil {
			return nil, fmt.Errorf("failed to read array elements: %w", err)
		}
		for i := range sl {
			sl[i] = binary.BigEndian.Uint64(data[i*8:])
		}
	case []int64:
		data := make([]byte, count*8)
		if _, err := io.ReadFull(r, data); err != nil {
			return nil, fmt.Errorf("failed to read array elements: %w", err)
		}
		for i := range sl {
			sl[i] = int64(binary.BigEndian.Uint64(data[i*8:]))
		}
	case []float64:
		data := make([]byte, count*8)
		if _, err := io.ReadFull(r, data); err != nil {
			return nil, fmt.Errorf("failed to read array elements: %w", err)
		}
		for i := range sl {
			sl[i] = math.Float64frombits(binary.BigEndian.Uint64(data[i*8:]))
		}

	// --- Variable-Length Sequences ---
	case []string:
		for i := range sl {
			length, err := readUint32(r)
			if err != nil {
				return nil, fmt.Errorf("failed to read string length at index %d: %w", i, err)
			}
			if length > MaxAllowedPacket {
				return nil, fmt.Errorf("string length %d exceeds MaxAllowedPacket at index %d", length, i)
			}

			buf := make([]byte, length)
			if _, err := io.ReadFull(r, buf); err != nil {
				return nil, fmt.Errorf("failed to read string data at index %d: %w", i, err)
			}
			sl[i] = string(buf)
		}
	case [][]byte:
		for i := range sl {
			length, err := readUint32(r)
			if err != nil {
				return nil, fmt.Errorf("failed to read []byte length at index %d: %w", i, err)
			}
			if length > MaxAllowedPacket {
				return nil, fmt.Errorf("[]byte length %d exceeds MaxAllowedPacket at index %d", length, i)
			}

			sl[i] = nil
			if length > 0 {
				buf := make([]byte, length)
				if _, err := io.ReadFull(r, buf); err != nil {
					return nil, fmt.Errorf("failed to read []byte data at index %d: %w", i, err)
				}
				sl[i] = buf
			}
		}

	case []*OnlyScalarTypesMsg:
		for i := range sl {
			set, err := readUint8(r)
			if err != nil {
				return nil, fmt.Errorf("failed to read object set/unset prefix for *OnlyScalarTypesMsg at index %d: %w", i, err)
			}

			if set == 0 {
				sl[i] = nil
				continue
			}

			typeID, fixedPayloadLen, overallPayloadLen, err := ReadMessageFrame(r)
			if err != nil {
				return nil, fmt.Errorf("failed to read frame header for *OnlyScalarTypesMsg at index %d: %w", i, err)
			}

			var msg OnlyScalarTypesMsg
			if typeID != msg.MessageTypeID() {
				return nil, fmt.Errorf("unexpected type ID %d for OnlyScalarTypesMsg, expected %d", typeID, msg.MessageTypeID())
			}

			OnlyScalarTypesMsg_reader := io.LimitReader(r, int64(overallPayloadLen))
			if err := msg.Unmarshal(OnlyScalarTypesMsg_reader, fixedPayloadLen, overallPayloadLen); err != nil {
				return nil, fmt.Errorf("failed to deserialize OnlyScalarTypesMsg: %w", err)
			}
			sl[i] = &msg
		}

	case []*OnlyVariableTypesMsg:
		for i := range sl {
			set, err := readUint8(r)
			if err != nil {
				return nil, fmt.Errorf("failed to read object set/unset prefix for *OnlyVariableTypesMsg at index %d: %w", i, err)
			}

			if set == 0 {
				sl[i] = nil
				continue
			}

			typeID, fixedPayloadLen, overallPayloadLen, err := ReadMessageFrame(r)
			if err != nil {
				return nil, fmt.Errorf("failed to read frame header for *OnlyVariableTypesMsg at index %d: %w", i, err)
			}

			var msg OnlyVariableTypesMsg
			if typeID != msg.MessageTypeID() {
				return nil, fmt.Errorf("unexpected type ID %d for OnlyVariableTypesMsg, expected %d", typeID, msg.MessageTypeID())
			}

			OnlyVariableTypesMsg_reader := io.LimitReader(r, int64(overallPayloadLen))
			if err := msg.Unmarshal(OnlyVariableTypesMsg_reader, fixedPayloadLen, overallPayloadLen); err != nil {
				return nil, fmt.Errorf("failed to deserialize OnlyVariableTypesMsg: %w", err)
			}
			sl[i] = &msg
		}

	case []*AllTypesFieldsMsg:
		for i := range sl {
			set, err := readUint8(r)
			if err != nil {
				return nil, fmt.Errorf("failed to read object set/unset prefix for *AllTypesFieldsMsg at index %d: %w", i, err)
			}

			if set == 0 {
				sl[i] = nil
				continue
			}

			typeID, fixedPayloadLen, overallPayloadLen, err := ReadMessageFrame(r)
			if err != nil {
				return nil, fmt.Errorf("failed to read frame header for *AllTypesFieldsMsg at index %d: %w", i, err)
			}

			var msg AllTypesFieldsMsg
			if typeID != msg.MessageTypeID() {
				return nil, fmt.Errorf("unexpected type ID %d for AllTypesFieldsMsg, expected %d", typeID, msg.MessageTypeID())
			}

			AllTypesFieldsMsg_reader := io.LimitReader(r, int64(overallPayloadLen))
			if err := msg.Unmarshal(AllTypesFieldsMsg_reader, fixedPayloadLen, overallPayloadLen); err != nil {
				return nil, fmt.Errorf("failed to deserialize AllTypesFieldsMsg: %w", err)
			}
			sl[i] = &msg
		}

	case []*RecursiveNestedMsg:
		for i := range sl {
			set, err := readUint8(r)
			if err != nil {
				return nil, fmt.Errorf("failed to read object set/unset prefix for *RecursiveNestedMsg at index %d: %w", i, err)
			}

			if set == 0 {
				sl[i] = nil
				continue
			}

			typeID, fixedPayloadLen, overallPayloadLen, err := ReadMessageFrame(r)
			if err != nil {
				return nil, fmt.Errorf("failed to read frame header for *RecursiveNestedMsg at index %d: %w", i, err)
			}

			var msg RecursiveNestedMsg
			if typeID != msg.MessageTypeID() {
				return nil, fmt.Errorf("unexpected type ID %d for RecursiveNestedMsg, expected %d", typeID, msg.MessageTypeID())
			}

			RecursiveNestedMsg_reader := io.LimitReader(r, int64(overallPayloadLen))
			if err := msg.Unmarshal(RecursiveNestedMsg_reader, fixedPayloadLen, overallPayloadLen); err != nil {
				return nil, fmt.Errorf("failed to deserialize RecursiveNestedMsg: %w", err)
			}
			sl[i] = &msg
		}

	case []*AllTypesOfArraysMsg:
		for i := range sl {
			set, err := readUint8(r)
			if err != nil {
				return nil, fmt.Errorf("failed to read object set/unset prefix for *AllTypesOfArraysMsg at index %d: %w", i, err)
			}

			if set == 0 {
				sl[i] = nil
				continue
			}

			typeID, fixedPayloadLen, overallPayloadLen, err := ReadMessageFrame(r)
			if err != nil {
				return nil, fmt.Errorf("failed to read frame header for *AllTypesOfArraysMsg at index %d: %w", i, err)
			}

			var msg AllTypesOfArraysMsg
			if typeID != msg.MessageTypeID() {
				return nil, fmt.Errorf("unexpected type ID %d for AllTypesOfArraysMsg, expected %d", typeID, msg.MessageTypeID())
			}

			AllTypesOfArraysMsg_reader := io.LimitReader(r, int64(overallPayloadLen))
			if err := msg.Unmarshal(AllTypesOfArraysMsg_reader, fixedPayloadLen, overallPayloadLen); err != nil {
				return nil, fmt.Errorf("failed to deserialize AllTypesOfArraysMsg: %w", err)
			}
			sl[i] = &msg
		}

	default:
		return nil, fmt.Errorf("unsupported array element type")
	}

	return slice, nil
}

func getElementType(item any) (uint16, error) {
	switch item.(type) {
	case bool:
		return TagBool, nil
	case int8:
		return TagInt8, nil
	case uint8:
		return TagUint8, nil
	case int16:
		return TagInt16, nil
	case uint16:
		return TagUint16, nil
	case int32:
		return TagInt32, nil
	case uint32:
		return TagUint32, nil
	case float32:
		return TagFloat32, nil
	case int64:
		return TagInt64, nil
	case uint64:
		return TagUint64, nil
	case float64:
		return TagFloat64, nil
	case string:
		return TagString, nil
	case []byte:
		return TagBytes, nil

	case *OnlyScalarTypesMsg:
		return TagOnlyScalarTypesMsg, nil

	case *OnlyVariableTypesMsg:
		return TagOnlyVariableTypesMsg, nil

	case *AllTypesFieldsMsg:
		return TagAllTypesFieldsMsg, nil

	case *RecursiveNestedMsg:
		return TagRecursiveNestedMsg, nil

	case *AllTypesOfArraysMsg:
		return TagAllTypesOfArraysMsg, nil

	default:
		return 0, fmt.Errorf("unsupported type: %T", item)
	}
}

func getArraySizer[T any](dimensions int) ArraySizer {
	var zero T
	elemType, err := getElementType(zero)
	if err != nil {
		panic(fmt.Errorf("unsupported type for array sizer: %T", zero))
	}
	switch dimensions {
	case 1:
		return &array1D[T]{EleType: elemType}
	case 2:
		return &array2D[T]{EleType: elemType}
	case 3:
		return &array3D[T]{EleType: elemType}
	default:
		panic(fmt.Errorf("unsupported array dimensions: %d", dimensions))
	}
}

func readUint8(r io.Reader) (uint8, error) {
	var buf [1]byte
	if _, err := io.ReadFull(r, buf[:]); err != nil {
		return 0, err
	}
	return buf[0], nil
}

func readUint32(r io.Reader) (uint32, error) {
	var buf [4]byte
	if _, err := io.ReadFull(r, buf[:]); err != nil {
		return 0, err
	}
	return binary.BigEndian.Uint32(buf[:]), nil
}

func readUint16(r io.Reader) (uint16, error) {
	var buf [2]byte
	if _, err := io.ReadFull(r, buf[:]); err != nil {
		return 0, err
	}
	return binary.BigEndian.Uint16(buf[:]), nil
}
